-- Up Migration
CREATE TABLE customers (
  id          BIGSERIAL PRIMARY KEY,
  full_name   TEXT NOT NULL,
  email       TEXT,
  phone       TEXT,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

ALTER TABLE orders ADD COLUMN customer_id BIGINT REFERENCES customers(id);
CREATE INDEX orders_customer_id_idx ON orders(customer_id);

-- Down Migration
ALTER TABLE orders DROP COLUMN customer_id;
DROP TABLE customers;
# Copy to .env for local development. Never commit real values.
DATABASE_URL=postgres://ledgerly:ledgerly@localhost:5432/ledgerly
JWT_SECRET=change-me-in-production
PAYMENT_WEBHOOK_SECRET=whsec_change_me
PORT=3000
LOG_LEVEL=info
# Retention (days) used by src/jobs/cleanup.ts
ORDER_RETENTION_DAYS=730
version: "3.9"

# Mirrors the production topology: the API runs as 3 stateless replicas behind
# the nginx load balancer. Anything that must be coordinated across requests
# has to live in Postgres, not in process memory.
services:
  api:
    build: .
    deploy:
      replicas: 3
    environment:
      DATABASE_URL: postgres://ledgerly:ledgerly@db:5432/ledgerly
      JWT_SECRET: ${JWT_SECRET}
      PAYMENT_WEBHOOK_SECRET: ${PAYMENT_WEBHOOK_SECRET}
      NODE_ENV: production
    depends_on:
      - db

  lb:
    image: nginx:1.25
    ports:
      - "8080:80"
    volumes:
      - ./deploy/nginx.conf:/etc/nginx/nginx.conf:ro
    depends_on:
      - api

  db:
    image: postgres:16
    environment:
      POSTGRES_USER: ledgerly
      POSTGRES_PASSWORD: ledgerly
      POSTGRES_DB: ledgerly
    volumes:
      - pgdata:/var/lib/postgresql/data

volumes:
  pgdata:
